<script setup lang="ts">
import {computed,ref} from 'vue'
import NowPlaying from '../components/NowPlaying.vue'
import TrackArt from '../components/TrackArt.vue'
import {dashboard,usable,type Track} from '../store'
import {t} from '../composables/useLocale'
import {run,refreshHistory} from '../composables/useDashboard'
import {duration,safeURL,songLinkURL,playedTime} from '../composables/useTrack'
import {requests,resolveQuery,clearPreview,confirmPreview,selectPreview,duplicateMessage,previewHistory,type Preview} from '../composables/useRequests'
import {queue,visibleQueue,filtered,schedule,dragStart,dragMove,dragEnd,cancelDrag,rowShift,suppressLink,useQueue} from '../composables/useQueue'
import {useLibrary} from '../composables/useLibrary'
useQueue();const library=useLibrary(),expandedListeners=ref(false)
const state=computed(()=>dashboard.snapshot),listeners=computed(()=>state.value?.listeners?.members||[])
const operations=computed(()=>state.value?.activity?.activity||[])
const disabled=computed(()=>!usable.value||state.value?.status==='disconnected')
function allowed(song:Preview){return usable.value&&song.allowed&&!song.pending&&(song.kind!=='playlist'||song.selected.length>0)}
function move(song:Track,to:number){void run('queue/move',{from:song.position,to,revision:state.value?.revision})}
function remove(song:Track){void run('queue/'+song.position,{revision:state.value?.revision},'DELETE')}
function clock(value:number){if(!Number.isFinite(value))return t('m0182');return new Date(value*1000).toLocaleTimeString(undefined,{hour:'2-digit',minute:'2-digit',hour12:false})}
function activityLabel(value:string){const labels:Record<string,string>={web:'m0183',text:'m0184',slash:'m0185',discord:'m0184'};return labels[value]?t(labels[value]):value}
</script>
<template><div id="play-view"><NowPlaying/><section class="card request" aria-labelledby="request-heading"><h2 id="request-heading" tabindex="-1">{{ t('m0245') }}</h2><form id="play-form" @submit.prevent="resolveQuery"><label class="sr-only" for="query">{{ t('m0246') }}</label><div class="input-row"><input id="query" v-model="requests.query" type="text" maxlength="2000" :placeholder="t('m0247')" required><button id="enqueue" class="primary" type="submit" :disabled="!usable||requests.loading" :aria-busy="requests.loading"><span>{{ t(requests.loading?'m0044':'m0248') }}</span></button></div><div class="request-mode"><label for="request-action">{{ t('m0249') }}</label><select id="request-action" v-model="requests.action" :disabled="!usable||requests.loading"><option value="play">{{ t('m0090') }}</option><option value="playnext">{{ t('m0250') }}</option></select></div></form><p v-if="requests.loading" role="status" class="hint request-loading">{{ t('m0079') }}</p><p v-if="requests.error" class="reason" role="alert">{{ requests.error }}</p><section id="preview-panel" :hidden="!requests.results.length" :aria-label="t('m0251')"><div class="section-top"><h3>{{ t('m0252') }}</h3><button id="preview-close" class="subtle" type="button" @click="clearPreview">{{ t('m0253') }}</button></div><div id="preview-results"><article v-for="(song,index) in requests.results" :key="song.preview_id+index" class="preview-item"><TrackArt :track="song"/><div><h3>{{ song.title }}</h3><small>{{ song.kind==='playlist'?t('m0081')+song.count+t('m0082')+song.checked_count+t('m0083')+song.eligible_count+t('m0084'):song.duration?duration(song.duration):t('m0085') }}</small><a :href="safeURL(song.url)||undefined" target="_blank" rel="noopener noreferrer">{{ song.url||t('m0086') }}</a><p v-if="song.reason||song.warning" :class="song.reason?'reason':'hint'">{{ song.reason||song.warning }}</p><p v-if="duplicateMessage(song.url)" class="hint duplicate-hint">{{ duplicateMessage(song.url) }}</p><template v-if="song.entries"><p class="hint playlist-next-hint">{{ t('m0092') }}</p><div class="selection-tools"><button type="button" :disabled="!usable||!song.allowed||song.pending" @click="selectPreview(song,true)">{{ t('m0093') }}</button><button type="button" :disabled="!usable||!song.allowed||song.pending" @click="selectPreview(song,false)">{{ t('m0094') }}</button><span>{{ t('m0087')+song.selected.length+t('m0033') }}</span></div><ol class="playlist-selection"><li v-for="item in song.entries" :key="item.item_id"><label><input v-model="song.selected" :value="item.item_id" type="checkbox" :disabled="!usable||!song.allowed||!item.allowed||song.pending" :aria-label="t('m0095')+item.title"><span>{{ (item.is_requested?t('m0096'):'')+item.title+' · '+(item.duration?duration(item.duration):t('m0097'))+(item.allowed?t('m0099'):t('m0098')+(item.reason||'')) }}</span></label><small v-if="duplicateMessage(item.url,true)" class="hint duplicate-hint">{{ duplicateMessage(item.url,true) }}</small></li></ol><div v-if="song.saveable" class="selection-tools"><label :for="'preview-name-'+index">{{ t('m0100') }}</label><input :id="'preview-name-'+index" v-model="song.name" maxlength="60" :disabled="library.busy.value"><button type="button" :disabled="!song.selected.length||!song.name.trim()||library.busy.value" @click="library.savePreview(song,song.selected,song.name)">{{ t(library.busy.value?'m0044':'m0101') }}</button></div></template></div><button class="primary" type="button" :disabled="!allowed(song)" :aria-busy="song.pending" @click="confirmPreview(song)">{{ song.pending?t('m0044'):song.kind==='playlist'?t('m0088')+song.selected.length+t('m0089'):t(song.allowed?'m0090':'m0091') }}</button><button v-if="song.kind!=='playlist'" type="button" :disabled="!allowed(song)||song.can_playnext===false&&requests.action==='play'" @click="confirmPreview(song,requests.action==='play'?'playnext':'play')">{{ t(requests.action==='play'?'m0104':'m0090') }}</button></article></div></section></section>
<section class="card queue" aria-labelledby="queue-heading"><div class="section-top"><h2 id="queue-heading">{{ t('m0254') }}<span id="queue-count">{{ state?.queue.length||0 }}</span>{{ t('m0255') }}<span id="queue-total">{{ schedule.total }}</span></h2><div class="queue-tools"><label for="queue-search">{{ t('m0257') }}<input id="queue-search" v-model="queue.search" type="search" maxlength="200" :placeholder="t('m0258')"></label><button id="shuffle" class="subtle" type="button" :disabled="disabled||!state?.queue.length||filtered" :title="filtered?t('m0174'):t('m0175')" @click="run('queue/shuffle',{revision:state?.revision})">{{ t('m0259') }}</button></div></div><div class="queue-filters" role="group" :aria-label="t('m0260')" :style="{'--selected':queue.mine?1:0}"><button id="queue-all" type="button" :aria-pressed="!queue.mine" @click="queue.mine=false">{{ t('m0261') }}</button><button id="queue-mine" type="button" :aria-pressed="queue.mine" @click="queue.mine=true">{{ t('m0170') }}</button></div><p id="queue-match-count" class="hint" role="status" aria-live="polite">{{ filtered?t('m0058')+visibleQueue.length+'／'+(state?.queue.length||0)+t('m0033'):'' }}</p><p id="queue-timing-note" class="hint">{{ state?.repeat==='all'?t('m0169'):'' }}</p><p v-if="filtered" class="hint">{{ t(queue.search?'m0171':'m0170')+t('m0172') }}</p><p id="drag-help" class="sr-only">{{ t('m0173') }}</p><div class="queue-head" aria-hidden="true"><span>＃</span><span>{{ t('m0262') }}</span><span>{{ t('m0263') }}</span></div><TransitionGroup id="queue" name="queue-row" tag="ol" aria-describedby="drag-help" :aria-busy="dashboard.loading"><li v-for="song in visibleQueue" :key="(song.position||0)+':'+song.url+':'+song.title" :data-position="song.position" :data-shift="rowShift(song)" :class="{'drag-active':queue.active&&song.position===queue.dragFrom,'drag-target':queue.active&&song.position===queue.target}" :style="queue.active?{transform:'translateY('+rowShift(song)+'px)'}:{}"><span class="number">{{ String(song.position).padStart(2,'0') }}</span><TrackArt :track="song" class="queue-art"/><div class="song"><p><a v-if="songLinkURL(song.url)" :href="songLinkURL(song.url)" target="_blank" rel="noopener noreferrer" @click="suppressLink">{{ song.title }}</a><span v-else>{{ song.title }}</span></p><small>{{ t('m0062')+(song.requester?.name||t('m0045')) }}</small><small class="queue-estimate">{{ schedule.times.get(song.position||0) }}</small></div><span class="song-length">{{ song.duration?duration(song.duration):t('m0063') }}</span><div class="actions"><button class="drag-handle" :disabled="disabled||filtered" :aria-label="t('m0064')+song.title+t('m0065')" aria-describedby="drag-help" :title="t(filtered?'m0066':'m0067')" @pointerdown="dragStart($event,song)" @pointermove="dragMove" @pointerup="dragEnd" @pointercancel="cancelDrag()" @lostpointercapture="cancelDrag()">⋮⋮</button><button :disabled="disabled||(song.position||0)<=1" :aria-label="t('m0068')+'：'+song.title" :title="t('m0068')" @click="move(song,(song.position||1)-1)">↑</button><button :disabled="disabled||(song.position||0)>=(state?.queue.length||0)" :aria-label="t('m0069')+'：'+song.title" :title="t('m0069')" @click="move(song,(song.position||0)+1)">↓</button><button :disabled="disabled" :aria-label="t('m0004')+'：'+song.title" :title="t('m0004')" @click="remove(song)">×</button><button v-if="safeURL(song.url)" class="library-save" :disabled="disabled||library.busy.value" :aria-label="t('m0198')+' '+song.title" @click="library.openSave(song)">＋</button></div></li></TransitionGroup><p id="queue-empty" class="empty" :hidden="!!visibleQueue.length||dashboard.loading">{{ t(queue.search?'m0059':queue.mine?'m0060':'m0061') }}</p><div v-if="dashboard.loading" class="queue-skeleton" role="status">{{ t('m0008') }}</div><section id="queue-recommendations" aria-labelledby="recommendation-heading" :hidden="!!state?.queue.length||!dashboard.history.length"><h3 id="recommendation-heading">{{ t('m0264') }}</h3><ol id="recommendation-list" class="history-list"><li v-for="(song,index) in dashboard.history.slice(0,5)" :key="song.url+index"><span>{{ song.title }}</span><button :disabled="!usable||requests.loading" @click="previewHistory(song)">{{ t('m0139') }}</button></li></ol></section></section>
<section class="card listeners" aria-labelledby="listeners-heading"><h2 id="listeners-heading">{{ t('m0267') }}</h2><p id="listeners-status" class="hint" role="status">{{ state?.listeners?.connected?t('m0176')+' · '+state.listeners.channel+' · '+listeners.length+t('m0177'):t('m0178') }}</p><div id="listeners-list" class="listeners-list"><span v-for="(person,index) in expandedListeners?listeners:listeners.slice(0,8)" :key="person.id||index" class="listener"><img v-if="safeURL(person.avatar)" :src="safeURL(person.avatar)" alt="" loading="lazy" referrerpolicy="no-referrer"><span>{{ person.name }}</span></span><button v-if="listeners.length>8" class="subtle" type="button" :aria-expanded="expandedListeners" @click="expandedListeners=!expandedListeners">{{ expandedListeners?'−':t('m0179')+(listeners.length-8)+t('m0177') }}</button></div></section><section class="card activity" aria-labelledby="activity-heading"><h2 id="activity-heading">{{ t('m0268') }}</h2><p id="activity-status" class="hint">{{ t(operations.length?'m0180':'m0181') }}</p><ol id="activity-list" class="activity-list"><li v-for="(item,index) in operations" :key="item.time+':'+index"><time>{{ clock(item.time) }}</time><span>{{ item.actor }} · {{ item.detail }}</span><small>{{ activityLabel(item.source) }}</small></li></ol></section><section class="card history" aria-labelledby="history-heading"><div class="section-top"><h2 id="history-heading">{{ t('m0264') }}</h2><button id="history-refresh" class="subtle" type="button" :disabled="!usable||dashboard.historyLoading" @click="refreshHistory">{{ t(dashboard.historyLoading?'m0044':'m0269') }}</button></div><p class="hint">{{ t('m0270') }}</p><p id="history-status" class="hint" role="status">{{ dashboard.historyError||(dashboard.historyLoading?t('m0008'):!dashboard.history.length?t('m0133'):'') }}</p><ol id="history-list" class="history-list"><li v-for="(song,index) in dashboard.history" :key="song.url+':'+index"><TrackArt :track="song"/><div><p><a :href="songLinkURL(song.url)||undefined" target="_blank" rel="noopener noreferrer">{{ song.title }}</a></p><small>{{ (song.duration?duration(song.duration):t('m0097'))+t('m0112')+(song.requester?.name||t('m0045'))+' · '+playedTime(song.played_at) }}</small></div><button :disabled="!usable||requests.loading" :aria-label="t('m0132')+song.title" @click="previewHistory(song)">{{ t('m0131') }}</button><button v-if="safeURL(song.url)" class="library-save" :disabled="!usable||library.busy.value" @click="library.openSave(song)">{{ t('m0198') }}</button></li></ol></section></div></template>
